CREATE TABLE crm_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(32) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(50) NOT NULL, email VARCHAR(100), phone VARCHAR(20), position VARCHAR(50), role VARCHAR(20) NOT NULL, enabled BIT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crm_customer (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, short_name VARCHAR(60), industry VARCHAR(60), level VARCHAR(10) NOT NULL DEFAULT 'B', status VARCHAR(20) NOT NULL, source VARCHAR(40), phone VARCHAR(30), email VARCHAR(120), address VARCHAR(240), notes VARCHAR(1000), next_follow_up_date DATE, owner_id BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_customer_owner(owner_id), INDEX idx_customer_status(status), INDEX idx_customer_next_follow(next_follow_up_date), CONSTRAINT fk_customer_owner FOREIGN KEY(owner_id) REFERENCES crm_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crm_contact (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, name VARCHAR(50) NOT NULL, title VARCHAR(60), phone VARCHAR(30), email VARCHAR(120), primary_contact BIT NOT NULL DEFAULT 0, notes VARCHAR(500), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_contact_customer(customer_id), CONSTRAINT fk_contact_customer FOREIGN KEY(customer_id) REFERENCES crm_customer(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crm_opportunity (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, amount DECIMAL(15,2) NOT NULL DEFAULT 0, stage VARCHAR(20) NOT NULL, probability INT NOT NULL DEFAULT 10, expected_close_date DATE, next_step VARCHAR(500), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_opportunity_customer(customer_id), INDEX idx_opportunity_owner_stage(owner_id,stage), CONSTRAINT fk_opportunity_customer FOREIGN KEY(customer_id) REFERENCES crm_customer(id), CONSTRAINT fk_opportunity_owner FOREIGN KEY(owner_id) REFERENCES crm_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crm_follow_up (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, opportunity_id BIGINT, creator_id BIGINT NOT NULL, method VARCHAR(20) NOT NULL, content VARCHAR(1000) NOT NULL, follow_up_at DATETIME(6) NOT NULL, next_action VARCHAR(500), next_follow_up_date DATE, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_follow_customer_time(customer_id,follow_up_at), INDEX idx_follow_creator(creator_id), CONSTRAINT fk_follow_customer FOREIGN KEY(customer_id) REFERENCES crm_customer(id), CONSTRAINT fk_follow_opportunity FOREIGN KEY(opportunity_id) REFERENCES crm_opportunity(id), CONSTRAINT fk_follow_creator FOREIGN KEY(creator_id) REFERENCES crm_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crm_sales_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, assignee_id BIGINT NOT NULL, customer_id BIGINT, title VARCHAR(120) NOT NULL, description VARCHAR(500), due_date DATE, priority VARCHAR(20) NOT NULL, completed BIT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_task_assignee_completed(assignee_id,completed), CONSTRAINT fk_task_assignee FOREIGN KEY(assignee_id) REFERENCES crm_user(id), CONSTRAINT fk_task_customer FOREIGN KEY(customer_id) REFERENCES crm_customer(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
